def parse(line):
    name, qty = line.strip().split(':', 1)
    return name, int(qty)

def total(lines):
    return max(parse(line)[1] for line in lines)

import unittest
from inventory import parse

class ParseTest(unittest.TestCase):
    def test_parse(self):
        self.assertEqual(parse('apple=5'), ('apple', 5))

if __name__ == '__main__':
    unittest.main()

